    "title": "Grunwald Monument",
    "summary": "Monument commemorating the 1410 Battle of Grunwald, a symbol of Polish victory and unity.",
    "description": "Welcome to the Grunwald Monument, a proud symbol of one of Poland’s greatest military victories. This impressive statue honors King Władysław II Jagiełło, who led Polish and Lithuanian forces to triumph over the Teutonic Knights in the Battle of Grunwald in 1410. The monument was unveiled in 1910 to mark the 500th anniversary of that epic battle, a time when Poland was still under foreign partitions and this statue became a powerful symbol of hope and national pride.\n\nThe monument was designed by Antoni Wiwulski and Franciszek Black and funded by Ignacy Jan Paderewski. Standing 24 meters tall, the granite pedestal supports a bronze equestrian statue of the king holding his sword high, ready for battle. Around the base, you’ll notice detailed reliefs depicting important figures like Grand Duke Vytautas and the defeated Teutonic Grand Master Ulrich von Jungingen, as well as allegorical images of knights and peasants united in victory.\n\nThis monument has inspired many artists and writers. The famous Polish painter Jan Matejko captured the battle’s drama in his iconic 1878 painting, which helped fuel the monument’s creation. When it was unveiled, the event drew an enormous crowd, including Ignacy Jan Paderewski, a pianist and statesman who played a key role in Poland’s independence movement.\n\nSadly, during World War II, Nazi Germany destroyed the monument because of its strong symbolism. It was reconstructed and officially unveiled again in 1976, with Marian Konieczny preparing the reconstruction from surviving documentation and models.\n\nToday, the Grunwald Monument stands proudly near the Barbican and the Tomb of the Unknown Soldier. It’s a gathering place for patriotic ceremonies and a reminder of Poland’s resilience. Keep that in mind as you admire this powerful symbol of history and hope.\n\nOur next stop: Jan Matejko Monument. Monument to Poland’s most famous historical painter.",
