    "narration": "Near Plac Jana Matejki, by the Planty and the Barbican, you’ll find yourself face-to-face with the statue of Jan Matejko, one of Poland’s greatest artists and a true Kraków legend. Matejko was born just a short walk from this area in 1838, and he went on to become the country’s most celebrated historical painter, known for his epic canvases that bring Poland’s dramatic past to life.\n\nThe monument was unveiled in 2013, on the 175th anniversary of Matejko’s birth and the 120th anniversary of his death. It was designed by sculptor Jan Tutaj. The bronze statue shows Matejko seated in an armchair set within a stylized picture frame, a reference to the canvases that made him famous.\n\nArtistically, the monument is a contemporary figurative tribute, with Matejko placed inside a symbolic picture frame rather than on a conventional 19th-century pedestal. It’s a fitting tribute to a man who dedicated his life to telling Poland’s story through art.\n\nMatejko’s influence goes far beyond painting. His works have inspired generations of writers, poets, and filmmakers, and his dramatic style is instantly recognizable to anyone familiar with Polish culture. His paintings hang in museums and palaces across the country, and he’s often referenced in novels and schoolbooks as the artist who made history come alive.\n\nThe monument stands near the Academy of Fine Arts that bears Matejko’s name and close to the route he would have taken between his family house on Floriańska Street and the school. Its placement by the Barbican makes it a natural pause between the Old Town walls and the lively traffic of Basztowa Street.\n\nThere’s a charming local tradition that says a moment beside Matejko’s frame may bring artistic inspiration, so take your time with this modern tribute to a very historical painter.\n\nToday, the Jan Matejko Monument is not just a tribute to a great artist, but a reminder of Kraków’s enduring creative spirit. It’s the perfect place to pause, reflect, and maybe even find a little inspiration of your own.",
    "teaser": "Our next stop: Jan Matejko Monument. Monument to Poland’s most famous historical painter.",
