    "id": 3,
    "stop_id": "florian_gate",
    "title": "Florian Gate",
    "summary": "Medieval city gate from the 14th century, a remnant of Krakow’s defensive structures.",
    "description": "Here we are at the iconic Florian Gate, the grand northern entrance to Kraków’s Old Town and a true symbol of the city’s medieval heritage. Built around 1307, this Gothic tower was part of the city’s original defensive walls and has stood watch over Kraków for more than seven centuries. In its heyday, it was the main gateway for travelers, merchants, and even kings arriving from the north.\n\nThe gate’s architecture is pure Gothic: tall, imposing, and built for defense, with thick limestone walls and a square tower rising over 30 meters high. Just above the arch, you’ll spot a stone relief of St. Florian, the city’s patron saint, who was believed to protect Kraków from fire and disaster. The Baroque-style metal “helmet” on top was added in the 17th century, giving the gate its distinctive silhouette. Inside, narrow staircases and arrow slits remind us that this was once a key military post.\n\nFlorian Gate has inspired generations of artists and writers. It appears in countless paintings and old photographs, and it’s often mentioned in Polish literature as the place where processions and parades began. The gate is also the starting point of the famous Royal Route, which led kings and dignitaries from here all the way to Wawel Castle for coronations and celebrations.\n\nOver the centuries, many important figures have passed through this gateway, including Polish monarchs, foreign ambassadors, and even Napoleon’s troops. During the partitions of Poland, the gate became a cherished symbol of national identity, and it was here that citizens would gather to celebrate important events or protest foreign rule.\n\nAnother story claims that if you stand beneath the arch at midnight, you might hear the faint sound of distant trumpets, echoing the city’s ancient call to arms.\n\nToday, Florian Gate is a beloved landmark and a favorite spot for street musicians, artists, and photographers. It forms part of the Museum of Kraków’s seasonal Defensive Walls route; the adjoining Pasamoników Tower contains displays on the old fortifications, city defenders, and weapons. Whether you’re here for the history or just to soak up the atmosphere, Florian Gate is a must-see stop on your Kraków adventure.\n\nOur next stop: Floriańska Street. Main thoroughfare connecting St. Florian’s Gate to the Main Square.",
