    "narration": "Now we arrive at the stunning Słowacki Theatre, one of Kraków’s most magnificent landmarks and a true temple of Polish drama. Opened in 1893, this theater was named after Juliusz Słowacki, one of Poland’s greatest Romantic poets, and it quickly became the city’s cultural showpiece.\n\nThe theater’s architecture is a feast for the eyes, inspired by the grand opera houses of Paris and Vienna. Designed by Jan Zawiejski, it features a lavish Neo-Baroque façade, complete with sculpted figures, columns, and a grand dome topped with allegorical statues. Step inside, and you’ll be greeted by a dazzling foyer with marble staircases, gilded stucco, and sparkling chandeliers. The auditorium is just as impressive, with plush red seats, ornate boxes, and a ceiling painted by the celebrated artist Antoni Tuch.\n\nOver the years, the Słowacki Theatre has hosted some of the most important premieres in Polish theater history, including the first performance of Stanisław Wyspiański’s “The Wedding” in 1901. Many of Poland’s greatest actors have graced its stage. The theater has been featured in numerous books, paintings, and films, often as a symbol of Kraków’s rich artistic tradition.\n\nThe building itself has seen its share of drama, both on and off the stage. During the Nazi occupation in World War II, the theater was closed and used as a German cultural center. After the war, it became a beacon of renewal, with performances that celebrated Polish identity and resilience.\n\nThere are some delightful legends connected to the Słowacki Theatre. Another tradition says that rubbing the bronze statue of Słowacki in the lobby before a performance will bring good luck to both actors and audience members.\n\nToday, the Słowacki Theatre remains at the heart of Kraków’s cultural life. It hosts a full calendar of plays, operas, and concerts, drawing theater lovers from across Poland and beyond. If you have the chance, step inside for a show or simply take a moment to admire the building’s opulent beauty. It’s a wonderful reminder that in Kraków, art and life are always intertwined.",
    "teaser": "Our next stop: Słowacki Theatre. Ornate 19th-century theatre, a Kraków architectural gem.",
