    "narration": "We’re now at the House of Jan Matejko, the birthplace and lifelong home of Poland’s most celebrated historical painter. This charming townhouse, tucked along bustling Floriańska Street, is where Matejko was born in 1838 and where he created many of his monumental works that brought Polish history to vivid life.\n\nThe building itself dates back to the 16th century and features a classic Kraków townhouse facade-narrow, tall, and adorned with decorative details that hint at its Renaissance roots. Inside, the rooms are filled with period furniture, personal belongings, and, of course, Matejko’s own sketches, paintings, and memorabilia. The walls are hung with portraits of Polish kings, battle scenes, and studies for his famous masterpieces like “The Battle of Grunwald” and “The Prussian Homage.”\n\nThis house has inspired generations of artists and writers. It’s mentioned in memoirs and novels as a place where history and art are inseparable, and it’s often depicted in paintings and illustrations about Kraków’s golden age of creativity. Matejko himself was a larger-than-life figure, and his home was a gathering place for fellow artists, students, and intellectuals.\n\nOver the years, the house has welcomed many important visitors, from Polish presidents to foreign dignitaries and famous painters. During the partitions, it was a quiet sanctuary where Matejko could work on his patriotic canvases, even as the world outside changed rapidly.\n\nThere are a few charming legends connected to this place. Another tradition claims that touching the artist’s favorite paintbrush, on display in the museum, will bring you a spark of creative genius.\n\nToday, the House of Jan Matejko is a branch of the National Museum and welcomes visitors from all over the world. School groups, art lovers, and curious travelers come here to learn about Matejko’s life and see where history was painted into being. Don’t miss the chance to step inside and feel the creative energy that still lingers in these historic rooms.",
