    "narration": "Welcome to the \"Pod Orłem\" Mansion, one of the Main Market Square’s most storied and architecturally distinctive townhouses. Built in the second half of the 14th century, this brick tenement has witnessed centuries of Kraków’s history, changing owners and functions as the city itself evolved. The mansion underwent its first major rebuild at the turn of the 14th and 15th centuries and received its Renaissance form, with an added outbuilding, in the 16th century.\n\nOver the years, \"Pod Orłem\" has been home to a variety of enterprises. In 1569, Wojciech Sulikowski opened a pharmacy on the ground floor, which became a fixture of the building’s identity for centuries. The house also hosted Parvi's café and snooker room in the 18th century, before returning to pharmacy use in 1809 as the \"Pod Białym Orłem\" (Under the White Eagle) pharmacy. In the late 19th century, the building was thoroughly renovated by its owner, Adolf Siedlecki, with designs by Władysław Ekielski. The first floor and outbuildings were added, and the mansion received the Gothic-Renaissance brick facade you see today.\n\nThe most eye-catching feature of the mansion is the sculpture at the top of the house-a phoenix, often mistaken for an eagle. This striking figure was designed by Stanisław Wyspiański and sculpted by Julian Szopiński, adding a touch of artistic flair and mystery to the building. Early 20th-century pharmacy furnishings with decorative eagles once graced the interior, though these were removed in the late 1990s.\n\nThe mansion’s walls have seen the comings and goings of Kraków’s citizens for generations, from chroniclers like Bartłomiej Kromer in the 16th century to the bustling café culture of the 18th and 19th centuries. Its presence on the Main Square means it has witnessed royal processions, public celebrations, and the everyday life of the city’s heart.\n\nToday, \"Pod Orłem\" stands as a testament to Kraków’s layered history and architectural beauty. While the pharmacy is no longer in operation, the building remains a cherished part of the Main Square’s landscape.",
