    "narration": "Now we’re standing before St. Mary’s Basilica, one of Kraków’s most beloved landmarks and a masterpiece of Gothic architecture. Construction began in the early 14th century, right on the site of an earlier church destroyed during a Mongol raid. Over the centuries, the basilica has watched over the Main Square, its two asymmetrical towers rising above the city like guardians.\n\nThe church’s brick façade is pure Gothic, with pointed arches, soaring windows, and an impressive rose window above the main entrance. But it’s the towers that really capture your attention: the taller one, known as the Hejnalica, was traditionally the city’s watchtower, while the shorter tower housed the church’s bells.\n\nStep inside, and you’ll be dazzled by the colorful interior, with its star-studded blue ceiling, gilded altars, and vibrant stained glass. The true treasure here is the magnificent wooden altarpiece carved by Veit Stoss in the late 15th century. This masterpiece is considered one of the greatest achievements of Gothic art in Europe, with its dramatic figures and intricate details telling the story of the Virgin Mary’s life.\n\nSt. Mary’s Basilica has inspired countless artists, poets, and musicians. The church is also home to the famous hejnał mariacki, the trumpet call played every hour from the taller tower. The melody always ends abruptly, a tradition that commemorates the legendary trumpeter who was shot while warning the city of a Mongol attack-a story every local knows by heart.\n\nOver the centuries, the basilica has hosted royal weddings, funerals, and major civic events. It’s been visited by kings, popes, and pilgrims from around the world. During World War II, the altarpiece was stolen by the Nazis but was miraculously recovered and returned to its rightful place after the war.\n\nToday, St. Mary’s Basilica is not only a working church but also a symbol of Kraków’s resilience and faith. Visitors flock here to admire its beauty, listen to the haunting trumpet call, and soak up the centuries of history that echo within its walls. Don’t miss the chance to step inside and experience the magic for yourself!",
    "teaser": "Our next stop: St. Mary’s Basilica. Iconic Gothic church with twin towers and a famous wooden altarpiece.",
