    "narration": "Just steps from the Main Market Square, tucked behind the soaring towers of St. Mary’s Basilica, you’ll find the intimate and atmospheric St. Barbara’s Church. Built in the 14th century, this little Gothic gem was originally funded in part by Queen Jadwiga and served as a cemetery chapel for the bustling parish next door. Over the centuries, it became a spiritual refuge for Kraków’s residents, especially during times of upheaval and occupation.\n\nThe church’s exterior is classic Gothic, with pointed arch windows, sturdy brick walls, and a simple, understated silhouette squeezed between burgher houses. In the 17th century, Baroque details were added, including a decorative dome and a richly adorned altar. One of the church’s most remarkable features is the Chapel of the Agony in the Garden, home to a moving sculptural group of Christ in Gethsemane attributed to Veit Stoss or his workshop. Don’t miss the stone pieta from the late 14th century, probably by a sculptor from the circle of the Master of the Beautiful Madonnas.\n\nInside, the church is a peaceful oasis, with a black-and-white checkerboard floor, marble-coated walls, and a dazzling Baroque altar framed by colorful stained glass. The ceiling is covered in frescoes of angels and saints, and the walls are lined with gilded pulpits and delicate polychrome decorations. The western chapel, with its late-Gothic ribbed vaults and intricate carvings, is considered one of the finest examples of Polish Gothic architecture.\n\nSt. Barbara’s Church has witnessed many chapters of Kraków’s history, from medieval funerals to Jesuit processions and the former Jesuit college next door, which housed Poland’s first clinical hospital in 1780. Professor Rafał Józef Czerwiakowski lectured and performed dissections there, provoking outrage among townsfolk who objected to autopsies on executed prisoners and the poor-a reminder of how science and faith sometimes clashed in the city’s past.\n\nThe church is often mentioned in guidebooks and art histories as a hidden treasure, and its tranquil interior has inspired both prayer and reflection for generations. Today, St. Barbara’s remains an active church and a favorite spot for those seeking a quiet moment away from the crowds.",
