    "narration": "Welcome to Planty Park, Kraków’s beloved green oasis that wraps around the Old Town like a soft, leafy embrace. This beautiful park was created in the early 19th century, after the city’s medieval defensive walls and moat were dismantled. Instead of leaving a barren ring around the city, the people of Kraków decided to plant gardens, trees, and winding paths, transforming the old fortifications into a place of relaxation and beauty.\n\nThe park stretches for about four kilometers and is divided into several charming sections, each with its own character. As you stroll beneath the shady chestnut and lime trees, you’ll spot elegant iron benches, ornate lamp posts, and a variety of statues and monuments dedicated to Kraków’s famous residents. The landscaping reflects the Romantic style popular in the 1800s, with curved paths, flowerbeds, and little ponds that invite you to linger.\n\nPlanty Park has been a favorite subject for painters and poets for generations. The gentle light filtering through the trees and the quiet corners have inspired countless works of art and literature. Nobel Prize-winning poet Wisława Szymborska often mentioned Planty in her verses, and the park has appeared in films as a symbol of the city’s peaceful, timeless spirit.\n\nOver the years, Planty has witnessed its share of history. It’s been the site of royal processions, student demonstrations, and even secret meetings during times of political unrest.\n\nThere are plenty of legends about Planty, too. Another tradition says that couples who share a kiss under the oldest tree in Planty will enjoy lifelong happiness.\n\nToday, Planty Park is a favorite spot for joggers, dog walkers, and anyone looking to escape the city’s hustle and bustle. Don’t be surprised if you see students studying, artists sketching, or musicians strumming a tune on a sunny bench. It’s a wonderful reminder that this park is truly the city’s living, breathing heart.",
    "teaser": "Our next stop: Planty Park. Green belt encircling the Old Town, created where the medieval walls once stood.",
