    "id": 12,
    "stop_id": "main_market_square",
    "title": "Main Market Square",
    "summary": "Europe’s largest medieval square, the heart of Kraków.",
    "description": "Welcome to Kraków’s Main Market Square, or Rynek Główny-a place that truly feels like the city’s beating heart. Laid out in 1257, this is the largest medieval town square in Europe, and for centuries it’s been the center of Kraków’s social, cultural, and commercial life. Imagine horses and carts rumbling over the cobblestones, merchants hawking their wares, and the lively buzz of townspeople gathering for everything from festivals to royal proclamations.\n\nThe square is a showcase of architectural styles, with elegant townhouses in pastel colors, Gothic towers, Renaissance arcades, and Baroque facades all jostling for your attention. The Cloth Hall dominates the center, while the twin towers of St. Mary’s Basilica rise dramatically above the crowds. The square’s layout is a perfect grid-a marvel of medieval urban planning-and it’s ringed by historic buildings with arcaded walkways and charming cafes.\n\nRynek Główny has appeared in countless paintings, novels, and films. It’s the setting for Nobel laureate Wisława Szymborska’s poetry, the backdrop for Andrzej Wajda’s movies, and the inspiration for generations of artists who have tried to capture its unique energy. The square has witnessed royal processions, peasant markets, and even the occasional duel!\n\nOver the centuries, the square has welcomed kings, popes, and presidents. It’s been the site of historic events, from the reading of the Constitution of May 3rd to mass gatherings during the Solidarity movement. During World War II, it was renamed Adolf Hitler Platz by the occupying Nazis, but after the war, it quickly reclaimed its role as the heart of Polish life.\n\nThere are plenty of legends swirling around the square. Another claims that if you circle the square three times on foot, you’ll return to Kraków again and again.\n\nToday, Rynek Główny is as lively as ever. It’s the stage for street performers, flower sellers, and open-air concerts. Every hour, you can hear the trumpet call from St. Mary’s Basilica, but the melody always ends abruptly-a tradition that honors a legendary trumpeter who was shot while warning the city of a Mongol attack. Soak in the atmosphere, snap some photos, and let yourself be swept up in the magic of Kraków’s Main Market Square.\n\nOur next stop: Cloth Hall (Sukiennice). Renaissance trading hall at the center of the Main Square.",
