    "id": 14,
    "stop_id": "st_adalbert_church",
    "title": "St. Adalbert’s Church",
    "summary": "One of Kraków’s oldest stone churches, dating to the 11th century.",
    "description": "Tucked into the southeastern corner of the Main Market Square, St. Adalbert’s Church is a small but remarkable piece of Kraków’s history. This modest stone church is actually one of the oldest surviving buildings in the city, with its origins dating all the way back to the 11th century. According to tradition, it was built on the spot where St. Adalbert of Prague preached to the townspeople before his fateful missionary journey to Prussia.\n\nThe church’s architecture is a fascinating blend of Romanesque and Baroque styles. The rounded stone walls and tiny windows at the base are original Romanesque elements from the early Middle Ages, while the elegant dome and stucco decorations were added in the 17th century, giving the church its current Baroque appearance. Step inside and you’ll find a peaceful, intimate interior with a beautiful Baroque altar and fragments of medieval frescoes.\n\nSt. Adalbert’s Church has inspired artists and writers for centuries, often appearing in paintings and old prints of the Main Square. Its simple silhouette is a favorite subject for photographers, especially at sunrise when the light glows softly on the ancient stones.\n\nOver the centuries, the church has witnessed countless historic events, from medieval fairs to royal processions and even public executions in the square outside. It’s been visited by kings, bishops, and pilgrims, and has served as a spiritual anchor in the ever-changing heart of Kraków.\n\nAnother story says that the church’s stones were brought here by angels, eager to help the townspeople build a place of worship.\n\nToday, St. Adalbert’s Church is still an active place of worship and a quiet refuge from the busy square outside. It hosts regular masses and occasional classical concerts, and its crypt houses a small archaeological museum where you can see the foundations of earlier structures.\n\nOur next stop: Eros Bendato Sculpture. Modern sculpture known as “The Head.”",
