    "narration": "Rising proudly on the western side of the Main Market Square, the Town Hall Tower is a striking reminder of Kraków’s medieval grandeur and a favorite spot for both locals and visitors. Built at the end of the 13th century, the tower was once part of a much larger Town Hall complex that served as the city’s administrative and judicial center. While the main hall was demolished in the 19th century, the tower survived and now stands as a symbol of Kraków’s resilience and history.\n\nThe Town Hall Tower is a classic example of Gothic architecture, constructed from sturdy stone and brick. Its slightly leaning silhouette (it tilts nearly half a meter to the east, thanks to centuries of shifting ground) adds a quirky charm. The tower rises to about 70 meters, topped with a Baroque dome added after a fire in the 17th century. Inside, visitors will find a steep wooden staircase leading to an observation deck that offers breathtaking panoramic views over the Main Square and the rooftops of the Old Town.\n\nOver the centuries, the tower has played many roles. It once housed the city’s treasury, archives, and even a prison in its dark, vaulted cellars. The Town Hall’s clock would chime out the hours for the entire city, and the building was the backdrop for royal ceremonies, public executions, and major civic events. The square below was often filled with crowds witnessing everything from victory parades to the infamous Prussian Homage in 1525.\n\nThe Town Hall Tower has inspired countless artists and writers, appearing in paintings, poems, and even in Kraków’s legends. Another tradition says that if you climb all the way to the top without stopping, you’ll be rewarded with good luck and clear skies for the rest of your visit.\n\nToday, the Town Hall Tower is open to the public as a branch of the Historical Museum of Kraków. Inside, you’ll find fascinating exhibits on the history of the city and the square, as well as a permanent photography exhibition. At the base of the tower, don’t miss the modern sculpture known as “The Head,” a favorite photo spot for visitors. Whether you’re here for the history, the views, or just a bit of medieval atmosphere, the Town Hall Tower is a must-see on your Kraków adventure.",
