    "narration": "Welcome to the Church of St. Anne, one of Kraków’s most magnificent Baroque landmarks and a beloved sanctuary for both worshippers and academics. The church stands on Św. Anny Street, just steps from the Jagiellonian University, and has been a center of faith and learning for centuries.\n\nThe earliest church on this site was mentioned as early as 1363, likely built of timber. After a fire in 1407, King Władysław II Jagiełło funded the construction of a new brick Gothic church. In 1418, the right of patronage passed to the Kraków Academy (now Jagiellonian University), and the church became closely tied to university life. By the late 17th century, the growing cult of St. John Cantius-a professor and later patron saint of the university-meant the old church was too small. In 1689, it was demolished to make way for the grand Baroque structure you see today, designed by Tylman van Gameren and inspired by Rome’s Sant’Andrea della Valle. The new church was consecrated in 1703.\n\nThe façade, set at an angle to the street, features two towers capped with late-Baroque domes, and its impact is all the more dramatic for being squeezed into a narrow street. The church is built on a Latin cross plan with a majestic dome and a ring of chapels connected by passageways. Inside, you’ll be dazzled by the rich Baroque decoration: stucco by Baldassare Fontana, frescoes by Carlo and Innocente Monti and Karol Dankwart, and a main altar with a painting of St. Anne by royal artist Jerzy Siemiginowski. The pulpit, carved with an angel by Antoni Frąckiewicz in 1727, and the late Baroque organ from 1723–24 are highlights. The sarcophagus of St. John Cantius, supported by allegorical figures representing university faculties, is a focal point in the right transept.\n\nThe church’s acoustics are legendary, making it a favorite venue for organ concerts and university ceremonies. For centuries, it has been the site of academic celebrations, student traditions, and the veneration of St. John Cantius. The church is often mentioned in guidebooks as a masterpiece of Polish Baroque, and its art and architecture have inspired generations of artists and writers.\n\nToday, St. Anne’s remains a vibrant part of university and city life, welcoming worshippers, scholars, and visitors from around the world.",
