    "narration": "Welcome to Collegium Maius, the oldest building of Poland’s oldest university and a true jewel of Kraków’s academic and architectural heritage. Standing at the corner of Św. Anny and Jagiellońska Streets, this remarkable structure has been the intellectual heart of the Jagiellonian University since the early 15th century. The university itself was founded in 1364 by King Casimir the Great, but it was King Władysław II Jagiełło, with funds bequeathed by Queen Jadwiga, who purchased this property for the university in 1400, marking the beginning of its storied history here.\n\nThe Collegium Maius is a masterpiece of Gothic architecture, rebuilt in the late 15th century into a harmonious quadrangle with arcaded galleries surrounding a peaceful courtyard. The building’s red brick facades, pointed arches, and decorative gables reflect the style of Kraków’s Golden Age. The central courtyard features a well from 1517, and the cloisters are supported by elegant stone columns. Upstairs, professors once lived and worked, while lectures and scholarly debates took place in the rooms below.\n\nInside, you’ll find a treasure trove of history: the Stuba Communis (professors’ common room), the Assembly Hall with a collection of paintings, the Libraria, and the Copernicus Room, which displays medieval astronomical instruments and an astrolabe from 1054. Nicolaus Copernicus, the famed astronomer who revolutionized our understanding of the universe, studied here in the 1490s. The museum also houses Gothic rector’s maces, the Jagiellonian globe, coins, medals, and rare scientific devices.\n\nCollegium Maius is woven into Kraków’s legends and the wider world of literature and art. The building’s historic interiors have inspired generations of writers, poets, and artists, and it’s often featured in films and books about Kraków’s scholarly traditions.\n\nOver the centuries, the university has weathered periods of decline and revival, from the patronage of Queen Jadwiga in the 15th century to its flourishing in the 19th and 20th centuries, when it attracted students from all over Europe. Nobel laureates like Wisława Szymborska and Ivo Andrić, and even Pope John Paul II, count among its distinguished alumni.\n\nToday, Collegium Maius is home to the Jagiellonian University Museum, welcoming visitors from around the world. You can wander through the historic rooms, admire medieval scientific instruments, and soak up the atmosphere of centuries of learning.",
