    "narration": "Welcome to Collegium Novum, the grand neo-Gothic centerpiece of the Jagiellonian University and one of Kraków’s most recognizable academic landmarks. Completed in 1887, this imposing building was designed by Feliks Księżarski for the university’s 500th anniversary, symbolizing a new era for Polish education during the time when Kraków was under Austrian rule. Its construction replaced the former academic boarding school “Jeruzalem,” which had been destroyed by fire.\n\nThe Collegium Novum stands out for its monumental red brick façade, pointed arches, decorative shields of the university’s founders, and tall, elegant windows. The building’s nearly square plan encloses two small internal courtyards, and the impressive portico faces the green belt of Planty Park. Inside, you’ll find grand stairways, vaulted ceilings, and richly decorated lecture halls, including the Assembly Hall (Aula) with its blue coffered ceiling and portraits of rectors and deans in heavy gilt frames.\n\nAs the university’s administrative heart, Collegium Novum houses the offices of the Rector, Vice-Rectors, and central administration. It’s also a venue for academic ceremonies, international conferences, concerts, and other cultural events. The building is surrounded by tradition and memory; in front of the main entrance grows the Liberty Oak, planted in 1919 to mark Poland’s regained independence.\n\nCollegium Novum is deeply woven into Poland’s modern history. On November 6, 1939, Nazi German authorities deceitfully summoned nearly 180 professors and staff here, only to arrest and deport them to concentration camps in the infamous “Sonderaktion Krakau.” A plaque in the building’s lecture hall commemorates this tragic event, honoring the professors’ sacrifice for the freedom of spirit and service to science and the nation.\n\nThe building often appears in literature, memoirs, and art as a symbol of Kraków’s intellectual life and resilience. Its dignified halls have welcomed Nobel laureates, heads of state, and generations of students, including Karol Wojtyła, who would later become Pope John Paul II.\n\nToday, Collegium Novum remains the vibrant administrative and ceremonial center of the Jagiellonian University. It’s a place where tradition meets modern academic life, and where the echoes of history are felt in every corridor.",
    "teaser": "Our next stop: Collegium Novum. Main building of Jagiellonian University, built in the 19th century.",
