    "narration": "Welcome to the Bishop’s Palace, the traditional residence of Kraków’s bishops since the late 14th century and the second largest palace in the city after Wawel Castle. This stately building has been at the heart of Kraków’s religious and social life for over 600 years, and its history is closely intertwined with the city’s most important events and personalities.\n\nThe palace was first mentioned in 1384, when Bishop Jan Radlica purchased a plot near the Franciscan Monastery. Over the centuries, it has survived fires, wars, and partitions, but always continued to serve its original purpose. After a devastating fire in 1462, the palace was rebuilt and later expanded by prominent bishops like Cardinal Zbigniew Oleśnicki and Bishop Piotr Gembicki, who added Renaissance and Baroque features. The building’s elegant stone portals, arcaded loggia, and rusticated façade reflect the changing tastes of the Renaissance and Baroque eras, while medieval fragments can still be found in the basement and courtyard.\n\nThe Bishop’s Palace is perhaps most famous as the Kraków home of Karol Wojtyła, who later became Pope John Paul II. During his visits to Kraków as pope, he would greet crowds from the “papal window” above the main entrance, delivering blessings and heartfelt messages late into the night. This tradition continues, and the window remains a place of pilgrimage and remembrance for people from all over the world.\n\nThe palace has inspired writers, historians, and artists, and its dignified silhouette appears in countless paintings and photographs of Kraków. It has hosted kings, queens, and countless dignitaries, and in recent years, even welcomed refugees fleeing conflict, as in 2022 when Archbishop Marek Jedraszewski opened its doors to those escaping the war in Ukraine.\n\nAnother tradition holds that if you pause beneath the window and make a wish, it will be heard by a higher power.\n\nToday, the Bishop’s Palace remains the seat of the Kraków metropolitan Curia and an active center of religious life. The papal window is a site of annual gatherings, especially on John Paul II’s birthday and other important anniversaries.",
