    "id": 27,
    "stop_id": "wyspianski_pavilion",
    "title": "Wyspiański Pavilion",
    "summary": "Modern exhibition space dedicated to artist Stanisław Wyspiański.",
    "description": "Welcome to the Wyspiański Pavilion, a striking blend of modern architecture and Polish artistic heritage right at the edge of Kraków’s Old Town. Opened in 2007, the Pavilion was the brainchild of renowned film director Andrzej Wajda, who envisioned a space to showcase the creative genius of Stanisław Wyspiański-one of Poland’s most celebrated artists, playwrights, and designers.\n\nThe Pavilion’s most distinctive feature is its trio of monumental stained glass windows in the main façade, created from Wyspiański’s original designs for Wawel Cathedral. These windows depict three legendary Polish figures: St. Stanislaus, Duke Henry the Pious, and King Casimir the Great. The images are dramatic and even a bit controversial-St. Stanislaus and Henry are shown at the moment of their deaths, while Casimir is depicted with a bare skull crowned, inspired by Wyspiański’s own experience witnessing the opening of the king’s casket centuries after his death. The windows were considered too somber for the cathedral in their day, so they waited nearly a century before finally being realized here.\n\nArchitecturally, the Pavilion is a marvel of contemporary design by Krzysztof Ingarden and Jacek Ewý. Its elongated, rounded form fits perfectly into a narrow Old Town plot, and the façade is made of thousands of ceramic tiles mounted on steel rods. These tiles can be moved to adjust the lighting inside, creating a dynamic interplay of light and shadow that changes throughout the day. The building’s transparency and modern lines offer a striking contrast to the surrounding historic architecture.\n\nInside, the Pavilion serves as a city information center, exhibition hall, and cultural venue. It regularly hosts art exhibitions, workshops, and events that celebrate both contemporary and traditional Polish creativity. The Pavilion is also a favorite subject for photographers and architecture enthusiasts, and its unique façade and stained glass have appeared in numerous art and travel publications.\n\nThe story of the Pavilion is full of local color: for decades, the plot stood empty, sparking debates and design competitions until Wajda’s vision finally brought it to life as part of the Kraków 2000 Festival. Today, the Pavilion is a lively hub for locals and visitors alike-a place to start your exploration of Kraków, discover new art, or simply enjoy the play of sunlight through Wyspiański’s visionary glass.\n\nOur next stop: Grodzka Street. One of Kraków’s oldest and most historic streets, forming part of the Royal Route and lined with architectural treasures, churches, and vibrant city life.",
