    "narration": "Welcome to St. Andrew’s Church, one of Kraków’s oldest and most remarkable landmarks, quietly nestled on Grodzka Street. Built between 1079 and 1098 by Palatine Sieciech, a powerful medieval statesman, this church is a rare and precious survivor from the Romanesque era. Its thick stone walls, small defensive windows, and twin octagonal towers weren’t just for show-this church was designed as a fortress as much as a place of worship. In fact, during the Mongol invasion of 1241, when much of Kraków was reduced to ruins, St. Andrew’s stood firm and sheltered the townspeople, earning the nickname “the lower castle.”\n\nThe church’s exterior is a classic example of Romanesque architecture, with its pale stone façade, rounded arches, and sturdy, almost austere silhouette. The two towers soar above the body of the church, their upper storeys adorned with beautiful double-arched windows. In the 17th century, Baroque domes were added to the towers, giving them a striking contrast to the medieval base. If you look closely along the lower façade, you’ll spot the small openings that once served as loopholes for archers-an unusual feature for a church, but a testament to its defensive role.\n\nStep inside, and you’ll be surprised by the lavish Baroque and Rococo interior, a transformation carried out in the early 18th century by Italian artist Baltazar Fontana. The church’s walls are adorned with intricate stucco work, gilded altars, and expressive paintings by Karol Dankwart. The pulpit, shaped like a boat, is a delightful Baroque touch, and the 18th-century organ in the choir loft is decorated in the ornate Rococo style. The contrast between the austere outside and the opulent interior is one of the church’s most captivating features.\n\nSt. Andrew’s has been home to the Order of Poor Clares since 1320, and their convent still adjoins the church to this day. Over the centuries, the church has inspired chroniclers, artists, and architects, and it’s often mentioned in guidebooks as the finest example of Romanesque architecture in Kraków.\n\nToday, St. Andrew’s is a peaceful sanctuary, often less crowded than its grander neighbors, making it a favorite spot for quiet reflection. The church regularly hosts classical concerts, taking advantage of its serene acoustics, and guided tours are available for those who want to delve deeper into its fascinating history. Andrew’s early in the morning, you might catch a glimpse of the Poor Clares in silent prayer, carrying on a tradition that has lasted for more than 700 years.",
