    "id": 32,
    "stop_id": "plac_sw_marii_magdalena",
    "title": "St. Mary Magdalene Square",
    "summary": "Historic square between Saints Peter and Paul and St. Andrew’s churches, once home to one of Kraków’s oldest churches.",
    "description": "Welcome to St. Mary Magdalene Square, a charming and atmospheric spot nestled between the grand facades of Saints Peter and Paul Church and St. Andrew’s Church. Though it’s a peaceful public space today, this square is steeped in history that stretches back to before Kraków officially became a city in 1257. In the early Middle Ages, this area was the heart of a settlement called Okół, where merchants, craftsmen, and even knights lived and traded.\n\nThe square takes its name from the Church of St. Mary Magdalene, one of Kraków’s oldest churches, which was likely founded around 1229 by Bishop Iwo Odrowąż. This Romanesque church stood at the center of the square for centuries, rebuilt after a fire in the 15th century, and was a focal point for the community. Sadly, both the church and an adjacent townhouse were demolished in the early 19th century, but you can still see the outline of the church’s foundations marked on the pavement-a subtle tribute to its presence.\n\nIn medieval times, this was a bustling market square and gathering place, where townspeople met for trade, socializing, and important announcements. Over the centuries, the square evolved along with the city, surrounded by historic townhouses and the impressive Baroque and Romanesque facades of the neighboring churches. The square’s current open form is the result of a 20th-century revitalization, which transformed the empty space left by the demolished church into a tranquil urban oasis.\n\nSt. Mary Magdalene Square is a favorite subject for artists and photographers, especially when the morning light catches the stone walls and the silhouettes of the churches. It’s also a popular site for open-air concerts, festivals, and even the occasional street performance.\n\nToday, this little square is a wonderful place to rest, admire the surrounding architecture, and imagine the layers of history beneath your feet.\n\nOur next stop: Kanonicza Street. One of Kraków’s oldest and most picturesque streets, lined with historic mansions once home to cathedral canons.",
