      "preview": "data:image/webp;base64,UklGRnAAAABXRUJQVlA4IGQAAABQAgCdASoQAAsAA4BaJQBOgMXwwEsF6v/33YAA/pEkGii6wmzuAWQcy77I9J9OcGxNWEhPKdE+qy4D8d+OD40Y6a+nwsAQE03mjJfM2K7gJQ3bpE7Q1hfyAqZhPCn1VgX5eAAA",
      "alt": "The house at 19 Kanonicza Street that holds the Archdiocesan Museum",
