    "narration": "Welcome to the Palace \"Under the Atlases,\" one of Kraków’s lesser-known architectural treasures and a striking example of Renaissance city mansions. The building’s name comes from the imposing stone atlantes-sculpted male figures-that support the upper part of the facade, giving the mansion its unique and memorable appearance.\n\nThe mansion’s origins date to the 16th century, a period when Kraków’s wealthy merchants and aristocrats competed to build the most impressive residences. The Renaissance style is evident in its symmetrical proportions, stonework, and decorative details, while the atlantes themselves are a rare feature in Kraków, making this facade especially eye-catching for passersby and art lovers.\n\nThroughout its history, the mansion has served many roles, from a private residence to housing shops and offices for Kraków’s townspeople. The building has witnessed centuries of city life, from the bustling trade of the Golden Age to the challenges of wars and partitions.\n\nThe mansion is sometimes mentioned in guidebooks and art histories as a hidden gem, and its facade is a popular subject for photographers and artists.\n\nToday, the building continues to serve various cultural and commercial purposes. Its beautifully restored facade and courtyard are occasionally open to the public during special events and guided tours, offering a glimpse into Kraków’s rich architectural heritage.",
