    "narration": "Welcome to Wawel Royal Castle and Cathedral, the crown jewel of Kraków and a place where Polish history truly comes alive. Perched high above the Vistula River, this fortified complex has been the seat of Polish kings and queens for centuries, and it’s no exaggeration to say that every stone here has a story to tell.\n\nThe castle’s history stretches back over a thousand years. The first fortifications on Wawel Hill appeared as early as the 10th century, and by the 14th century, King Casimir III the Great had transformed it into a grand Gothic residence. Over the years, the castle was expanded and rebuilt by successive monarchs, each leaving their mark in the form of Romanesque, Gothic, Renaissance, and Baroque architecture. Italian architects Bartolomeo Berrecci and Francesco Fiorentino gave the castle its Renaissance elegance in the 16th century, while the cathedral’s towers and chapels showcase a mix of styles and centuries.\n\nWawel Castle has always been at the center of Poland’s cultural and political life. It was the site of royal coronations and burials, and the halls once echoed with the debates of the Polish parliament. The cathedral, with its soaring nave and glittering chapels, is the final resting place of kings, national heroes, and poets. Inside, you’ll find treasures like the Sigismund Bell, the largest historic bell in Poland, and the tombs of monarchs including Sigismund III Vasa and John III Sobieski.\n\nThe castle and cathedral have inspired countless works of art and literature. Jan Matejko’s monumental paintings, Sienkiewicz’s novels, and even modern films have all drawn on the legends and drama of Wawel. The site is also home to the famous Dragon’s Den, a cave beneath the hill said to have once housed a fearsome dragon slain by the city’s mythical founder, Krakus. There’s even a dragon statue at the base of the hill that breathes real fire for visitors!\n\nOver the centuries, Wawel has hosted popes, presidents, and visiting dignitaries from around the world. It survived fires, wars, and foreign occupations-including a period as an Austrian military barracks after the partitions of Poland. In the 20th century, the castle was restored and became a museum, showcasing royal treasures, tapestries, and one of Europe’s finest collections of Ottoman tents.\n\nToday, Wawel Castle and Cathedral are the most visited sites in Kraków, drawing millions of visitors each year. The castle’s courtyards, gardens, and art galleries are open to the public, and the cathedral remains an active place of worship and national celebration. So take your time exploring this extraordinary place, and let yourself be swept up in the magic and majesty of Wawel.",
    "teaser": "Our next stop: Wawel Royal Castle & Cathedral. Kraków’s most iconic historic site, seat of Polish kings and spiritual heart of the nation.",
